-- Native POS schema for Supabase SQL Editor. Safe to re-run.
-- Applies webhook POS tables (if missing) then every 20260828 native-POS migration in order.
-- Do not run 20260828120000_drop_affiliate_program.sql here.
-- Generated by scripts/generate-apply-native-pos.mjs — edit the migrations, then regenerate.

-- ═══════════════════════════════════════════════════════════════════════════
-- scripts/apply-pos-integrations.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Apply POS integration tables (run once in Supabase → SQL Editor).
-- Combines:
--   supabase/migrations/20260709180000_pos_integrations.sql
--   supabase/migrations/20260709183000_pos_oauth_states.sql
-- Safe to re-run (IF NOT EXISTS / DROP POLICY IF EXISTS).

-- Requires public.is_org_member(uuid) from migration 20260624120000_fix_org_membership_rls_recursion.sql

-- ── pos_connections + pos_sales_events ────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.pos_connections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  provider text NOT NULL CHECK (provider IN ('generic', 'yoco', 'square')),
  label text NOT NULL DEFAULT 'POS Connection',
  webhook_token text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(24), 'hex'),
  webhook_secret text NOT NULL DEFAULT encode(gen_random_bytes(32), 'hex'),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  config jsonb NOT NULL DEFAULT '{}'::jsonb,
  last_event_at timestamptz,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_pos_connections_org_id ON public.pos_connections(org_id);
CREATE INDEX IF NOT EXISTS idx_pos_connections_webhook_token ON public.pos_connections(webhook_token);

CREATE TABLE IF NOT EXISTS public.pos_sales_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  connection_id uuid NOT NULL REFERENCES public.pos_connections(id) ON DELETE CASCADE,
  external_id text NOT NULL,
  provider text NOT NULL,
  status text NOT NULL DEFAULT 'completed',
  total_amount numeric(14, 2) NOT NULL,
  currency text NOT NULL DEFAULT 'ZAR',
  payment_method text,
  occurred_at timestamptz NOT NULL,
  items jsonb NOT NULL DEFAULT '[]'::jsonb,
  inventory_result jsonb,
  inventory_applied boolean NOT NULL DEFAULT false,
  raw_payload jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pos_sales_events_connection_external_unique UNIQUE (connection_id, external_id)
);

CREATE INDEX IF NOT EXISTS idx_pos_sales_events_org_occurred
  ON public.pos_sales_events(org_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_pos_sales_events_connection_id
  ON public.pos_sales_events(connection_id);

ALTER TABLE public.pos_connections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pos_sales_events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "pos_connections_org_select" ON public.pos_connections;
CREATE POLICY "pos_connections_org_select"
  ON public.pos_connections
  FOR SELECT
  TO authenticated
  USING (public.is_org_member(org_id));

DROP POLICY IF EXISTS "pos_connections_org_manage" ON public.pos_connections;
CREATE POLICY "pos_connections_org_manage"
  ON public.pos_connections
  FOR ALL
  TO authenticated
  USING (public.is_company_admin_for_org(org_id))
  WITH CHECK (public.is_company_admin_for_org(org_id));

DROP POLICY IF EXISTS "pos_sales_events_org_select" ON public.pos_sales_events;
CREATE POLICY "pos_sales_events_org_select"
  ON public.pos_sales_events
  FOR SELECT
  TO authenticated
  USING (public.is_org_member(org_id));

GRANT EXECUTE ON FUNCTION public.adjust_inventory_stock(uuid, uuid, integer, text, text, uuid) TO service_role;

GRANT ALL ON TABLE public.pos_connections TO service_role;
GRANT ALL ON TABLE public.pos_sales_events TO service_role;

-- ── pos_oauth_states (Square OAuth CSRF) ──────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.pos_oauth_states (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  provider text NOT NULL CHECK (provider IN ('square', 'yoco')),
  state_token text NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_pos_oauth_states_expires_at ON public.pos_oauth_states(expires_at);

ALTER TABLE public.pos_oauth_states ENABLE ROW LEVEL SECURITY;

GRANT ALL ON TABLE public.pos_oauth_states TO service_role;

-- Notify PostgREST to reload schema cache (Supabase API)
NOTIFY pgrst, 'reload schema';

-- If DELETE /api/pos/connections/:id fails with FK errors, also run:
-- supabase/migrations/20260709190000_pos_sales_events_cascade_delete.sql
-- supabase/migrations/20260709191000_pos_delete_connection_rpc.sql

CREATE OR REPLACE FUNCTION public.delete_pos_connection(
  p_org_id uuid,
  p_connection_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  deleted boolean := false;
BEGIN
  IF p_org_id IS NULL OR p_connection_id IS NULL THEN
    RETURN false;
  END IF;

  DELETE FROM public.pos_sales_events
  WHERE connection_id = p_connection_id;

  DELETE FROM public.pos_connections
  WHERE id = p_connection_id
    AND org_id = p_org_id
  RETURNING true INTO deleted;

  RETURN COALESCE(deleted, false);
END;
$$;

REVOKE ALL ON FUNCTION public.delete_pos_connection(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.delete_pos_connection(uuid, uuid) TO service_role;

NOTIFY pgrst, 'reload schema';

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828160000_native_pos_checkout.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Native Paidly POS: same pos_sales_events + inventory RPC as Yoco/Square ingress.
-- provider 'paidly' is an in-app till, not a webhook connection.
-- Requires pos_connections + pos_sales_events (scripts/apply-pos-integrations.sql).

DO $$
BEGIN
  IF to_regclass('public.pos_connections') IS NULL OR to_regclass('public.pos_sales_events') IS NULL THEN
    RAISE EXCEPTION 'pos_connections/pos_sales_events missing. Run scripts/apply-pos-integrations.sql first, then re-run this file.';
  END IF;
END $$;

ALTER TABLE public.pos_connections
  DROP CONSTRAINT IF EXISTS pos_connections_provider_check;

ALTER TABLE public.pos_connections
  ADD CONSTRAINT pos_connections_provider_check
  CHECK (provider IN ('generic', 'yoco', 'square', 'paidly'));

-- Native till sales are not tied to a webhook connection.
ALTER TABLE public.pos_sales_events
  ALTER COLUMN connection_id DROP NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_pos_connections_one_paidly_per_org
  ON public.pos_connections (org_id)
  WHERE provider = 'paidly';

ALTER TABLE public.pos_sales_events
  ADD COLUMN IF NOT EXISTS receipt_number text,
  ADD COLUMN IF NOT EXISTS client_id uuid,
  ADD COLUMN IF NOT EXISTS company_id uuid,
  ADD COLUMN IF NOT EXISTS cashier_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS sale_kind text NOT NULL DEFAULT 'sale',
  ADD COLUMN IF NOT EXISTS parent_event_id uuid REFERENCES public.pos_sales_events(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS amount_tendered numeric(14, 2),
  ADD COLUMN IF NOT EXISTS change_due numeric(14, 2);

DO $$
BEGIN
  IF to_regclass('public.clients') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.pos_sales_events DROP CONSTRAINT IF EXISTS pos_sales_events_client_id_fkey';
    EXECUTE $c$
      ALTER TABLE public.pos_sales_events
        ADD CONSTRAINT pos_sales_events_client_id_fkey
        FOREIGN KEY (client_id) REFERENCES public.clients(id) ON DELETE SET NULL
    $c$;
  END IF;
  IF to_regclass('public.companies') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.pos_sales_events DROP CONSTRAINT IF EXISTS pos_sales_events_company_id_fkey';
    EXECUTE $c$
      ALTER TABLE public.pos_sales_events
        ADD CONSTRAINT pos_sales_events_company_id_fkey
        FOREIGN KEY (company_id) REFERENCES public.companies(id) ON DELETE SET NULL
    $c$;
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'pos_sales_events_sale_kind_check'
      AND conrelid = 'public.pos_sales_events'::regclass
  ) THEN
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_sale_kind_check
      CHECK (sale_kind IN ('sale', 'return'));
  END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS idx_pos_sales_events_org_receipt
  ON public.pos_sales_events (org_id, receipt_number)
  WHERE receipt_number IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_pos_sales_events_parent
  ON public.pos_sales_events (parent_event_id)
  WHERE parent_event_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_pos_sales_events_cashier
  ON public.pos_sales_events (org_id, cashier_id, occurred_at DESC);

COMMENT ON COLUMN public.pos_sales_events.sale_kind IS
  'sale = retail checkout; return = restock against parent_event_id.';
COMMENT ON COLUMN public.pos_connections.provider IS
  'generic | yoco | square (webhook adapters) | paidly (native till).';

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828180000_payment_intents.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Canonical Payment Intent layer (Document Engine / POS ↔ customer payment rails).
-- PayFast is SaaS subscription billing only — it must not appear as a customer-payment provider.
-- POS settlement remains pos_sales_events (not invoice payments, not payment_history).
-- Safe in SQL Editor: uses gen_random_uuid(); FKs to optional tables are added only when those relations exist.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS public.payment_intents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  source_kind text NOT NULL CHECK (source_kind IN ('document', 'pos')),
  document_id uuid,
  document_type text,
  pos_sale_event_id uuid,
  provider text NOT NULL,
  amount numeric(14, 2) NOT NULL CHECK (amount >= 0),
  currency text NOT NULL DEFAULT 'ZAR',
  status text NOT NULL DEFAULT 'pending' CHECK (
    status IN ('pending', 'requires_action', 'processing', 'paid', 'failed', 'cancelled', 'expired', 'refunded')
  ),
  external_id text,
  idempotency_key text,
  client_id uuid,
  company_id uuid,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  expires_at timestamptz,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payment_intents_pos_provider_check CHECK (
    (source_kind = 'pos' AND provider IN ('cash', 'ozow'))
    OR (source_kind = 'document' AND provider IN ('ozow'))
  ),
  CONSTRAINT payment_intents_document_ref_check CHECK (
    source_kind <> 'document' OR document_id IS NOT NULL
  )
);

DO $$
BEGIN
  IF to_regclass('public.pos_sales_events') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.payment_intents DROP CONSTRAINT IF EXISTS payment_intents_pos_sale_event_id_fkey';
    EXECUTE $c$
      ALTER TABLE public.payment_intents
        ADD CONSTRAINT payment_intents_pos_sale_event_id_fkey
        FOREIGN KEY (pos_sale_event_id) REFERENCES public.pos_sales_events(id) ON DELETE SET NULL
    $c$;
  ELSE
    RAISE NOTICE 'pos_sales_events missing — skip payment_intents.pos_sale_event_id FK (run scripts/apply-pos-integrations.sql)';
  END IF;

  IF to_regclass('public.clients') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.payment_intents DROP CONSTRAINT IF EXISTS payment_intents_client_id_fkey';
    EXECUTE $c$
      ALTER TABLE public.payment_intents
        ADD CONSTRAINT payment_intents_client_id_fkey
        FOREIGN KEY (client_id) REFERENCES public.clients(id) ON DELETE SET NULL
    $c$;
  END IF;

  IF to_regclass('public.companies') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.payment_intents DROP CONSTRAINT IF EXISTS payment_intents_company_id_fkey';
    EXECUTE $c$
      ALTER TABLE public.payment_intents
        ADD CONSTRAINT payment_intents_company_id_fkey
        FOREIGN KEY (company_id) REFERENCES public.companies(id) ON DELETE SET NULL
    $c$;
  END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS idx_payment_intents_org_idempotency
  ON public.payment_intents (org_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_payment_intents_org_created
  ON public.payment_intents (org_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_payment_intents_pos_sale
  ON public.payment_intents (pos_sale_event_id)
  WHERE pos_sale_event_id IS NOT NULL;

DO $$
BEGIN
  IF to_regclass('public.pos_sales_events') IS NULL THEN
    RAISE NOTICE 'pos_sales_events missing — skip payment_intent_id column';
    RETURN;
  END IF;
  EXECUTE 'ALTER TABLE public.pos_sales_events ADD COLUMN IF NOT EXISTS payment_intent_id uuid';
  EXECUTE 'ALTER TABLE public.pos_sales_events DROP CONSTRAINT IF EXISTS pos_sales_events_payment_intent_id_fkey';
  EXECUTE $c$
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_payment_intent_id_fkey
      FOREIGN KEY (payment_intent_id) REFERENCES public.payment_intents(id) ON DELETE SET NULL
  $c$;
  EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pos_sales_events_payment_intent ON public.pos_sales_events (payment_intent_id) WHERE payment_intent_id IS NOT NULL';
  EXECUTE $c$
    COMMENT ON COLUMN public.pos_sales_events.payment_intent_id IS
      'Intent that verified this till sale. Cash and Ozow go through payment_intents first.'
  $c$;
END $$;

ALTER TABLE public.payment_intents ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "payment_intents_org_select" ON public.payment_intents;
CREATE POLICY "payment_intents_org_select"
  ON public.payment_intents
  FOR SELECT
  TO authenticated
  USING (public.is_org_member(org_id));

GRANT ALL ON TABLE public.payment_intents TO service_role;
GRANT SELECT ON TABLE public.payment_intents TO authenticated;

COMMENT ON TABLE public.payment_intents IS
  'Customer payment handoff. source_kind=pos settles to pos_sales_events; source_kind=document settles to invoice payments. PayFast is not a provider here.';
COMMENT ON COLUMN public.payment_intents.provider IS
  'Customer rail: cash (till-verified) or ozow (online). Never payfast.';

