DO $$
BEGIN
  IF to_regclass('public.payment_intents') IS NULL THEN
    RAISE EXCEPTION 'payment_intents missing. Apply 20260828180000_payment_intents.sql first.';
  END IF;
END $$;

ALTER TABLE public.payment_intents
  DROP CONSTRAINT IF EXISTS payment_intents_pos_provider_check;

ALTER TABLE public.payment_intents
  ADD CONSTRAINT payment_intents_pos_provider_check CHECK (
    (source_kind = 'pos' AND provider IN ('cash', 'ozow', 'card_terminal'))
    OR (source_kind = 'document' AND provider IN ('ozow'))
  );

COMMENT ON COLUMN public.payment_intents.provider IS
  'Customer rail: cash (till-verified), ozow (digital/EFT), card_terminal (hardware — not faked). Never payfast.';

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828200000_pos_sale_invoice.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Optional tax-invoice copy of a settled POS sale.
-- POS checkout does not create invoices. Convert is opt-in (Customer requests invoice).
-- Money stays on pos_sales_events. Stock already moved with source=pos; skip invoice inventory triggers.

DO $$
BEGIN
  IF to_regclass('public.invoices') IS NULL THEN
    RAISE EXCEPTION 'invoices missing — cannot add pos_sale_event_id';
  END IF;
  IF to_regclass('public.pos_sales_events') IS NULL THEN
    RAISE EXCEPTION 'pos_sales_events missing. Run scripts/apply-pos-integrations.sql first.';
  END IF;
END $$;

ALTER TABLE public.invoices
  ADD COLUMN IF NOT EXISTS pos_sale_event_id uuid;

DO $$
BEGIN
  EXECUTE 'ALTER TABLE public.invoices DROP CONSTRAINT IF EXISTS invoices_pos_sale_event_id_fkey';
  EXECUTE $c$
    ALTER TABLE public.invoices
      ADD CONSTRAINT invoices_pos_sale_event_id_fkey
      FOREIGN KEY (pos_sale_event_id) REFERENCES public.pos_sales_events(id) ON DELETE SET NULL
  $c$;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS idx_invoices_pos_sale_event_id
  ON public.invoices (pos_sale_event_id)
  WHERE pos_sale_event_id IS NOT NULL;

ALTER TABLE public.pos_sales_events
  ADD COLUMN IF NOT EXISTS invoice_id uuid;

DO $$
BEGIN
  EXECUTE 'ALTER TABLE public.pos_sales_events DROP CONSTRAINT IF EXISTS pos_sales_events_invoice_id_fkey';
  EXECUTE $c$
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_invoice_id_fkey
      FOREIGN KEY (invoice_id) REFERENCES public.invoices(id) ON DELETE SET NULL
  $c$;
END $$;

CREATE INDEX IF NOT EXISTS idx_pos_sales_events_invoice_id
  ON public.pos_sales_events (invoice_id)
  WHERE invoice_id IS NOT NULL;

COMMENT ON COLUMN public.invoices.pos_sale_event_id IS
  'Optional tax-invoice copy of a settled POS sale. Not a new receivable. Money stays on pos_sales_events; do not insert invoice payments.';

COMMENT ON COLUMN public.pos_sales_events.invoice_id IS
  'Optional invoices.id when the customer requested a tax invoice for this till sale.';

CREATE OR REPLACE FUNCTION public.handle_invoice_paid()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
DECLARE
  r RECORD;
  v_current_stock integer;
  v_qty integer;
  v_delta integer;
BEGIN
  -- POS already decremented stock via adjust_inventory_stock (source=pos).
  IF NEW.pos_sale_event_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'paid' AND (OLD.status IS DISTINCT FROM 'paid') THEN

    FOR r IN
      SELECT ii.service_id AS product_id, ii.quantity AS qty
      FROM public.invoice_items ii
      JOIN public.services s ON s.id = ii.service_id
      WHERE ii.invoice_id = NEW.id
        AND COALESCE(s.item_type, 'service') = 'product'
    LOOP
      SELECT stock_quantity INTO v_current_stock
      FROM public.services
      WHERE id = r.product_id
        AND org_id = NEW.org_id
      FOR UPDATE;

      v_qty := GREATEST(COALESCE(r.qty, 0)::integer, 0);
      v_delta := -LEAST(v_qty, COALESCE(v_current_stock, 0));

      IF v_delta <> 0 THEN
        PERFORM public.apply_inventory_movement(
          r.product_id, NEW.org_id, v_delta, 'out', 'invoice', NEW.id
        );
      END IF;
    END LOOP;

  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.handle_invoice_reversal()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
DECLARE
  r RECORD;
  v_qty integer;
BEGIN
  IF NEW.pos_sale_event_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'paid' AND NEW.status <> 'paid' THEN

    FOR r IN
      SELECT ii.service_id AS product_id, ii.quantity AS qty
      FROM public.invoice_items ii
      JOIN public.services s ON s.id = ii.service_id
      WHERE ii.invoice_id = NEW.id
        AND COALESCE(s.item_type, 'service') = 'product'
    LOOP
      v_qty := GREATEST(COALESCE(r.qty, 0)::integer, 0);
      IF v_qty <> 0 THEN
        PERFORM public.apply_inventory_movement(
          r.product_id, NEW.org_id, v_qty, 'in', 'invoice_reversal', NEW.id
        );
      END IF;
    END LOOP;

  END IF;

  RETURN NEW;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828210000_pos_registers.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Native POS register: a till identity on an org brand (public.companies).
-- Paidly has no locations table — do not invent a multi-site model here.
-- Sale SoR stays pos_sales_events. This is not a parallel POS ledger, session, or payments table.

CREATE TABLE IF NOT EXISTS public.pos_registers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  company_id uuid,
  name text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  assigned_staff_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  opening_balance numeric(14, 2) NOT NULL DEFAULT 0 CHECK (opening_balance >= 0),
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pos_registers_name_not_blank CHECK (char_length(btrim(name)) > 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_pos_registers_org_name
  ON public.pos_registers (org_id, lower(btrim(name)));

CREATE INDEX IF NOT EXISTS idx_pos_registers_org_status
  ON public.pos_registers (org_id, status);

CREATE INDEX IF NOT EXISTS idx_pos_registers_company
  ON public.pos_registers (company_id)
  WHERE company_id IS NOT NULL;

DO $$
BEGIN
  IF to_regclass('public.companies') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.pos_registers DROP CONSTRAINT IF EXISTS pos_registers_company_id_fkey';
    EXECUTE $c$
      ALTER TABLE public.pos_registers
        ADD CONSTRAINT pos_registers_company_id_fkey
        FOREIGN KEY (company_id) REFERENCES public.companies(id) ON DELETE SET NULL
    $c$;
  END IF;
END $$;

DO $$
BEGIN
  IF to_regclass('public.pos_sales_events') IS NULL THEN
    RAISE NOTICE 'pos_sales_events missing — skip register_id';
    RETURN;
  END IF;
  EXECUTE 'ALTER TABLE public.pos_sales_events ADD COLUMN IF NOT EXISTS register_id uuid';
  EXECUTE 'ALTER TABLE public.pos_sales_events DROP CONSTRAINT IF EXISTS pos_sales_events_register_id_fkey';
  EXECUTE $c$
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_register_id_fkey
      FOREIGN KEY (register_id) REFERENCES public.pos_registers(id) ON DELETE SET NULL
  $c$;
  EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pos_sales_events_register ON public.pos_sales_events (register_id) WHERE register_id IS NOT NULL';
END $$;

ALTER TABLE public.pos_registers ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "pos_registers_org_select" ON public.pos_registers;
CREATE POLICY "pos_registers_org_select"
  ON public.pos_registers
  FOR SELECT
  TO authenticated
  USING (public.is_org_member(org_id));

DROP POLICY IF EXISTS "pos_registers_org_manage" ON public.pos_registers;
CREATE POLICY "pos_registers_org_manage"
  ON public.pos_registers
  FOR ALL
  TO authenticated
  USING (public.is_company_admin_for_org(org_id))
  WITH CHECK (public.is_company_admin_for_org(org_id));

GRANT ALL ON TABLE public.pos_registers TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.pos_registers TO authenticated;

COMMENT ON TABLE public.pos_registers IS
  'Physical till identity. Belongs to org + optional brand (companies). No locations table exists — do not add a site model here. Opening balance is the cash float, not a sale.';

COMMENT ON COLUMN public.pos_registers.company_id IS
  'Brand (public.companies.id). Same trading identity as invoices.company_id.';

COMMENT ON COLUMN public.pos_registers.assigned_staff_id IS
  'Operational assignment. Checkout cashier_id is still the signed-in user.';

COMMENT ON COLUMN public.pos_registers.opening_balance IS
  'Expected cash float in the drawer. Not POS sale money, not invoice payments.';

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'pos_sales_events' AND column_name = 'register_id'
  ) THEN
    EXECUTE $c$
      COMMENT ON COLUMN public.pos_sales_events.register_id IS
        'Till that recorded this sale. Optional so Yoco/Square ingress still works without a native register.'
    $c$;
  END IF;
END $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828220000_pos_register_sessions.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- POS register shift sessions (cash drawer), not Auth sessions.
-- Sale SoR stays pos_sales_events. Closed sessions are immutable.
-- If pos_registers is missing (SQL Editor applied this file first), create it here.

CREATE TABLE IF NOT EXISTS public.pos_registers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  company_id uuid,
  name text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  assigned_staff_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  opening_balance numeric(14, 2) NOT NULL DEFAULT 0 CHECK (opening_balance >= 0),
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pos_registers_name_not_blank CHECK (char_length(btrim(name)) > 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_pos_registers_org_name
  ON public.pos_registers (org_id, lower(btrim(name)));

CREATE INDEX IF NOT EXISTS idx_pos_registers_org_status
  ON public.pos_registers (org_id, status);

CREATE INDEX IF NOT EXISTS idx_pos_registers_company
  ON public.pos_registers (company_id)
  WHERE company_id IS NOT NULL;

DO $$
BEGIN
  IF to_regclass('public.companies') IS NOT NULL THEN
    EXECUTE 'ALTER TABLE public.pos_registers DROP CONSTRAINT IF EXISTS pos_registers_company_id_fkey';
    EXECUTE $c$
      ALTER TABLE public.pos_registers
        ADD CONSTRAINT pos_registers_company_id_fkey
        FOREIGN KEY (company_id) REFERENCES public.companies(id) ON DELETE SET NULL
    $c$;
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.pos_register_sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  register_id uuid NOT NULL REFERENCES public.pos_registers(id) ON DELETE RESTRICT,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  opening_balance numeric(14, 2) NOT NULL DEFAULT 0 CHECK (opening_balance >= 0),
  cash_sales numeric(14, 2) NOT NULL DEFAULT 0 CHECK (cash_sales >= 0),
  cash_refunds numeric(14, 2) NOT NULL DEFAULT 0 CHECK (cash_refunds >= 0),
  expected_cash numeric(14, 2) NOT NULL DEFAULT 0,
  closing_cash numeric(14, 2) CHECK (closing_cash IS NULL OR closing_cash >= 0),
  variance numeric(14, 2),
  opened_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  closed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  opened_at timestamptz NOT NULL DEFAULT now(),
  closed_at timestamptz,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pos_register_sessions_closed_complete CHECK (
    (status = 'open' AND closed_at IS NULL AND closing_cash IS NULL AND variance IS NULL)
    OR
    (status = 'closed' AND closed_at IS NOT NULL AND closing_cash IS NOT NULL AND variance IS NOT NULL)
  )
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_pos_register_sessions_one_open
  ON public.pos_register_sessions (register_id)
  WHERE status = 'open';

CREATE INDEX IF NOT EXISTS idx_pos_register_sessions_org_opened
  ON public.pos_register_sessions (org_id, opened_at DESC);

CREATE INDEX IF NOT EXISTS idx_pos_register_sessions_register
  ON public.pos_register_sessions (register_id, opened_at DESC);

DO $$
BEGIN
  IF to_regclass('public.pos_sales_events') IS NULL THEN
    RAISE NOTICE 'pos_sales_events missing — skip session_id';
    RETURN;
  END IF;
  EXECUTE 'ALTER TABLE public.pos_sales_events ADD COLUMN IF NOT EXISTS session_id uuid';
  EXECUTE 'ALTER TABLE public.pos_sales_events DROP CONSTRAINT IF EXISTS pos_sales_events_session_id_fkey';
  EXECUTE $c$
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_session_id_fkey
      FOREIGN KEY (session_id) REFERENCES public.pos_register_sessions(id) ON DELETE SET NULL
  $c$;
  EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pos_sales_events_session ON public.pos_sales_events (session_id) WHERE session_id IS NOT NULL';
END $$;

ALTER TABLE public.pos_register_sessions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "pos_register_sessions_org_select" ON public.pos_register_sessions;
CREATE POLICY "pos_register_sessions_org_select"
  ON public.pos_register_sessions
  FOR SELECT
  TO authenticated
  USING (public.is_org_member(org_id));

DROP POLICY IF EXISTS "pos_register_sessions_org_write" ON public.pos_register_sessions;
CREATE POLICY "pos_register_sessions_org_write"
  ON public.pos_register_sessions
  FOR INSERT
  TO authenticated
  WITH CHECK (public.is_org_member(org_id));

DROP POLICY IF EXISTS "pos_register_sessions_org_update" ON public.pos_register_sessions;
CREATE POLICY "pos_register_sessions_org_update"
  ON public.pos_register_sessions
  FOR UPDATE
  TO authenticated
  USING (public.is_org_member(org_id) AND status = 'open')
  WITH CHECK (public.is_org_member(org_id));

CREATE OR REPLACE FUNCTION public.pos_register_session_immutable()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'closed' THEN
      RAISE EXCEPTION 'Completed POS sessions cannot be edited';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status = 'closed' THEN
    RAISE EXCEPTION 'Completed POS sessions cannot be edited';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS tr_pos_register_session_immutable ON public.pos_register_sessions;
CREATE TRIGGER tr_pos_register_session_immutable
BEFORE UPDATE OR DELETE ON public.pos_register_sessions
FOR EACH ROW
EXECUTE FUNCTION public.pos_register_session_immutable();

GRANT ALL ON TABLE public.pos_register_sessions TO service_role;
GRANT SELECT, INSERT, UPDATE ON TABLE public.pos_register_sessions TO authenticated;

COMMENT ON TABLE public.pos_register_sessions IS
  'Cash-drawer shift on a POS register. Not Auth. Closed rows are immutable. Cash totals snapshot at close from pos_sales_events.';

COMMENT ON COLUMN public.pos_register_sessions.opening_balance IS
  'Cash counted into the drawer when the shift opens. Prefills from pos_registers.opening_balance.';

COMMENT ON COLUMN public.pos_register_sessions.expected_cash IS
  'opening_balance + cash_sales - cash_refunds. Snapshotted at close.';

COMMENT ON COLUMN public.pos_register_sessions.variance IS
  'closing_cash - expected_cash. Set only when the session is closed.';

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'pos_sales_events' AND column_name = 'session_id'
  ) THEN
    EXECUTE $c$
      COMMENT ON COLUMN public.pos_sales_events.session_id IS
        'Open register shift that recorded this native till sale. External Yoco/Square ingress may omit it.'
    $c$;
  END IF;
END $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828230000_pos_return_audit.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Append-only POS returns. The original sale is never deleted to reverse money.
-- Refund state is derived from child sale_kind=return rows and snapshotted on the sale.
-- Card/digital provider refunds (Ozow / card_terminal) are not V1: stamp pending_provider
-- and keep payment_intents.refund_of_intent_id for a later refund intent.

DO $$
BEGIN
  IF to_regclass('public.pos_sales_events') IS NULL THEN
    RAISE EXCEPTION 'pos_sales_events missing. Run scripts/apply-pos-integrations.sql first.';
  END IF;
END $$;

ALTER TABLE public.pos_sales_events
  ADD COLUMN IF NOT EXISTS refund_status text NOT NULL DEFAULT 'none',
  ADD COLUMN IF NOT EXISTS refunded_amount numeric(14, 2) NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS refund_rail text,
  ADD COLUMN IF NOT EXISTS original_payment_intent_id uuid;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'pos_sales_events_refund_status_check'
      AND conrelid = 'public.pos_sales_events'::regclass
  ) THEN
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_refund_status_check
      CHECK (refund_status IN ('none', 'partial', 'full'));
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'pos_sales_events_refund_rail_check'
      AND conrelid = 'public.pos_sales_events'::regclass
  ) THEN
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_refund_rail_check
      CHECK (refund_rail IS NULL OR refund_rail IN ('till_cash', 'pending_provider', 'provider'));
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'pos_sales_events_refunded_amount_check'
      AND conrelid = 'public.pos_sales_events'::regclass
  ) THEN
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_refunded_amount_check
      CHECK (refunded_amount >= 0);
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_pos_sales_events_refund_status
  ON public.pos_sales_events (org_id, refund_status)
  WHERE sale_kind = 'sale' AND refund_status <> 'none';

UPDATE public.pos_sales_events
SET refund_rail = CASE
  WHEN lower(coalesce(payment_method, 'cash')) = 'cash' THEN 'till_cash'
  ELSE 'pending_provider'
END
WHERE sale_kind = 'return'
  AND refund_rail IS NULL;

DO $$
BEGIN
  IF to_regclass('public.payment_intents') IS NULL THEN
    RAISE NOTICE 'payment_intents missing — skip refund_of_intent_id (apply 20260828180000_payment_intents.sql)';
    RETURN;
  END IF;
  EXECUTE 'ALTER TABLE public.payment_intents ADD COLUMN IF NOT EXISTS refund_of_intent_id uuid';
  EXECUTE 'ALTER TABLE public.payment_intents DROP CONSTRAINT IF EXISTS payment_intents_refund_of_intent_id_fkey';
  EXECUTE $c$
    ALTER TABLE public.payment_intents
      ADD CONSTRAINT payment_intents_refund_of_intent_id_fkey
      FOREIGN KEY (refund_of_intent_id) REFERENCES public.payment_intents(id) ON DELETE SET NULL
  $c$;
  EXECUTE 'CREATE INDEX IF NOT EXISTS idx_payment_intents_refund_of ON public.payment_intents (refund_of_intent_id) WHERE refund_of_intent_id IS NOT NULL';
  EXECUTE $c$
    COMMENT ON COLUMN public.payment_intents.refund_of_intent_id IS
      'Future provider refund intent pointing at the original paid intent. Unused in V1.'
  $c$;
  EXECUTE 'ALTER TABLE public.pos_sales_events DROP CONSTRAINT IF EXISTS pos_sales_events_original_payment_intent_id_fkey';
  EXECUTE $c$
    ALTER TABLE public.pos_sales_events
      ADD CONSTRAINT pos_sales_events_original_payment_intent_id_fkey
      FOREIGN KEY (original_payment_intent_id) REFERENCES public.payment_intents(id) ON DELETE SET NULL
  $c$;
END $$;

-- Financial identity is immutable. Operational fields (inventory flags, invoice
-- link, refund snapshot, client attach, refund_rail completion) may still change.
-- DELETE is not blocked here: pos_connections.connection_id ON DELETE CASCADE
-- must still remove events when a connection is deleted. Returns must INSERT a
-- child row instead of DELETE/UPDATE of totals.

CREATE OR REPLACE FUNCTION public.pos_sales_event_financial_immutable()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NEW.total_amount IS DISTINCT FROM OLD.total_amount
     OR NEW.items IS DISTINCT FROM OLD.items
     OR NEW.sale_kind IS DISTINCT FROM OLD.sale_kind
     OR NEW.parent_event_id IS DISTINCT FROM OLD.parent_event_id
     OR NEW.payment_method IS DISTINCT FROM OLD.payment_method
     OR NEW.occurred_at IS DISTINCT FROM OLD.occurred_at
     OR NEW.receipt_number IS DISTINCT FROM OLD.receipt_number
     OR NEW.amount_tendered IS DISTINCT FROM OLD.amount_tendered
     OR NEW.change_due IS DISTINCT FROM OLD.change_due
     OR NEW.currency IS DISTINCT FROM OLD.currency
     OR NEW.external_id IS DISTINCT FROM OLD.external_id
     OR NEW.provider IS DISTINCT FROM OLD.provider
     OR NEW.connection_id IS DISTINCT FROM OLD.connection_id
     OR NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.cashier_id IS DISTINCT FROM OLD.cashier_id
     OR NEW.register_id IS DISTINCT FROM OLD.register_id
     OR NEW.session_id IS DISTINCT FROM OLD.session_id
     OR NEW.company_id IS DISTINCT FROM OLD.company_id
     OR NEW.original_payment_intent_id IS DISTINCT FROM OLD.original_payment_intent_id
  THEN
    RAISE EXCEPTION 'POS sales cannot change financial fields; record a return instead';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS tr_pos_sales_event_financial_immutable ON public.pos_sales_events;
CREATE TRIGGER tr_pos_sales_event_financial_immutable
BEFORE UPDATE ON public.pos_sales_events
FOR EACH ROW
EXECUTE FUNCTION public.pos_sales_event_financial_immutable();

COMMENT ON COLUMN public.pos_sales_events.refund_status IS
  'Snapshot on the original sale: none | partial | full. Derived from child return events. Original totals are never rewritten.';

COMMENT ON COLUMN public.pos_sales_events.refunded_amount IS
  'Sum of abs(child return total_amount). Original total_amount stays the sale total.';

COMMENT ON COLUMN public.pos_sales_events.refund_rail IS
  'On return rows: till_cash (drawer), pending_provider (V1 card/digital restock), provider (future Ozow/terminal refund).';

COMMENT ON COLUMN public.pos_sales_events.original_payment_intent_id IS
  'Original sale payment_intents.id copied onto the return. V1 does not mark that intent refunded.';

COMMENT ON COLUMN public.pos_sales_events.sale_kind IS
  'sale = retail checkout; return = append-only restock/refund against parent_event_id. Never delete the original sale to reverse it.';

