-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828270000_organizations_business_type.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Tenant business model: POS is optional. Service orgs stay on invoices/quotes/clients.
-- retail = Paidly + till; mixed = invoices + till. NULL = service (do not force POS).

ALTER TABLE public.organizations
  ADD COLUMN IF NOT EXISTS business_type text;

ALTER TABLE public.organizations
  DROP CONSTRAINT IF EXISTS organizations_business_type_check;

ALTER TABLE public.organizations
  ADD CONSTRAINT organizations_business_type_check
  CHECK (
    business_type IS NULL
    OR business_type IN ('service', 'retail', 'mixed')
  );

COMMENT ON COLUMN public.organizations.business_type IS
  'How the tenant sells: service (documents only), retail (POS), mixed (documents + POS). NULL is treated as service — POS stays off.';

-- Keep the till for orgs that already run POS (registers or sales).
DO $$
BEGIN
  IF to_regclass('public.pos_registers') IS NOT NULL THEN
    EXECUTE $u$
      UPDATE public.organizations o
      SET business_type = 'mixed'
      WHERE o.business_type IS NULL
        AND EXISTS (SELECT 1 FROM public.pos_registers r WHERE r.org_id = o.id)
    $u$;
  END IF;
  IF to_regclass('public.pos_sales_events') IS NOT NULL THEN
    EXECUTE $u$
      UPDATE public.organizations o
      SET business_type = 'mixed'
      WHERE o.business_type IS NULL
        AND EXISTS (SELECT 1 FROM public.pos_sales_events s WHERE s.org_id = o.id)
    $u$;
  END IF;
END $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828280000_plans_pos_feature.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Canonical SaaS feature key `pos` on Business+ catalog rows.
-- Enforcement is FAMILY_FEATURES + requireFeature('pos') — not a per-user/org allowlist.

DO $$
BEGIN
  IF to_regclass('public.plans') IS NULL THEN
    RAISE NOTICE 'plans missing — skip pos feature catalog row update';
    RETURN;
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'plans'
      AND column_name = 'features'
  ) THEN
    RAISE NOTICE 'plans.features missing — skip pos feature catalog row update';
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'plans'
      AND column_name = 'plan_family'
  ) THEN
    UPDATE public.plans
    SET features = COALESCE(features, '[]'::jsonb) || '["pos"]'::jsonb
    WHERE (
        plan_family IN ('business', 'growth', 'enterprise')
        OR slug IN (
          'sme',
          'corporate',
          'business_monthly',
          'business_annual',
          'growth_monthly',
          'growth_annual',
          'enterprise_custom'
        )
      )
      AND NOT (COALESCE(features, '[]'::jsonb) ? 'pos');
  ELSE
    UPDATE public.plans
    SET features = COALESCE(features, '[]'::jsonb) || '["pos"]'::jsonb
    WHERE slug IN (
        'sme',
        'corporate',
        'business_monthly',
        'business_annual',
        'growth_monthly',
        'growth_annual',
        'enterprise_custom'
      )
      AND NOT (COALESCE(features, '[]'::jsonb) ? 'pos');
  END IF;
END $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828290000_pos_staff_invite.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- POS-only staff invites: same Auth + memberships, job_function = pos.
-- Shareable till link is /invite?token=…&next=POS. Do not add a second POS login.

CREATE OR REPLACE FUNCTION public.normalize_job_function(raw text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE lower(trim(replace(coalesce(raw, ''), ' ', '_')))
    WHEN 'human_resources' THEN 'hr'
    WHEN 'sales' THEN 'sales'
    WHEN 'hr' THEN 'hr'
    WHEN 'finance' THEN 'finance'
    WHEN 'operations' THEN 'operations'
    WHEN 'support' THEN 'support'
    WHEN 'marketing' THEN 'marketing'
    WHEN 'it' THEN 'it'
    WHEN 'pos' THEN 'pos'
    WHEN 'cashier' THEN 'pos'
    WHEN 'till' THEN 'pos'
    WHEN 'general' THEN 'general'
    ELSE 'general'
  END;
$$;

DO $$
BEGIN
  IF to_regclass('public.company_invites') IS NULL THEN
    RAISE EXCEPTION 'company_invites missing — apply invite lifecycle migrations before POS staff invites';
  END IF;
END $$;

ALTER TABLE public.company_invites
  ADD COLUMN IF NOT EXISTS job_function text NOT NULL DEFAULT 'general';

ALTER TABLE public.company_invites
  ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'company_admin';

ALTER TABLE public.company_invites
  ADD COLUMN IF NOT EXISTS transfer_org_ownership boolean NOT NULL DEFAULT false;

ALTER TABLE public.memberships
  ADD COLUMN IF NOT EXISTS job_function text NOT NULL DEFAULT 'general';

COMMENT ON COLUMN public.company_invites.job_function IS
  'Copied onto memberships.job_function on accept. pos = till-only staff (RBAC role stays employee).';

COMMENT ON COLUMN public.company_invites.source IS
  'Who issued the invite: company_admin | platform_admin | pos';

CREATE OR REPLACE FUNCTION public.validate_company_invite_token(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.company_invites%ROWTYPE;
  v_org_name text;
BEGIN
  IF p_token IS NULL OR trim(p_token) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_token');
  END IF;

  SELECT * INTO v_row
  FROM public.company_invites
  WHERE token = trim(p_token)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_row.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', v_row.status);
  END IF;

  IF v_row.expires_at < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'expired');
  END IF;

  SELECT o.name INTO v_org_name
  FROM public.organizations o
  WHERE o.id = v_row.org_id;

  RETURN jsonb_build_object(
    'ok', true,
    'invite_id', v_row.id,
    'email', v_row.email,
    'role', v_row.role,
    'job_function', public.normalize_job_function(coalesce(v_row.job_function, 'general')),
    'source', coalesce(v_row.source, 'company_admin'),
    'org_id', v_row.org_id,
    'company_name', coalesce(v_org_name, 'your company'),
    'expires_at', v_row.expires_at,
    'transfer_org_ownership', coalesce(v_row.transfer_org_ownership, false)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.validate_company_invite_token(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_company_invite_token(text) TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.accept_company_invite_token(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_meta jsonb;
  v_invite_id uuid;
  v_org_id uuid;
  v_role text;
  v_membership_role text;
  v_job_function text;
  v_email text;
  v_onboarding_form text;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated');
  END IF;

  v_meta := public.validate_company_invite_token(p_token);
  IF (v_meta->>'ok')::boolean IS NOT TRUE THEN
    RETURN v_meta;
  END IF;

  v_invite_id := (v_meta->>'invite_id')::uuid;
  v_org_id := (v_meta->>'org_id')::uuid;
  v_role := lower(trim(v_meta->>'role'));
  v_job_function := public.normalize_job_function(
    COALESCE(v_meta->>'job_function', 'general')
  );
  IF lower(trim(coalesce(v_meta->>'source', ''))) = 'pos' THEN
    v_job_function := 'pos';
  END IF;

  SELECT lower(trim(email)) INTO v_email FROM auth.users WHERE id = v_user_id;
  IF v_email IS NULL OR v_email <> lower(trim(v_meta->>'email')) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'email_mismatch');
  END IF;

  v_membership_role := CASE
    WHEN v_role IN ('admin', 'owner', 'company_admin') THEN 'admin'
    WHEN v_role = 'manager' THEN 'manager'
    ELSE 'employee'
  END;

  IF v_job_function = 'pos' THEN
    v_membership_role := 'employee';
  END IF;

  v_onboarding_form := CASE
    WHEN v_membership_role IN ('admin', 'owner') THEN 'admin'
    ELSE 'member'
  END;

  IF EXISTS (
    SELECT 1 FROM public.memberships m
    WHERE m.org_id = v_org_id AND m.user_id = v_user_id
  ) THEN
    UPDATE public.memberships
    SET role = v_membership_role,
        job_function = v_job_function
    WHERE org_id = v_org_id AND user_id = v_user_id;
  ELSE
    INSERT INTO public.memberships (org_id, user_id, role, job_function)
    VALUES (v_org_id, v_user_id, v_membership_role, v_job_function);
  END IF;

  IF coalesce((v_meta->>'transfer_org_ownership')::boolean, false) THEN
    UPDATE public.organizations SET owner_id = v_user_id WHERE id = v_org_id;
    UPDATE public.memberships SET role = 'owner', job_function = 'general' WHERE org_id = v_org_id AND user_id = v_user_id;
    v_onboarding_form := 'admin';
    v_membership_role := 'owner';
    v_job_function := 'general';
  END IF;

  PERFORM public.upsert_user_company_role(
    v_user_id, v_org_id, public.normalize_company_role(v_membership_role), v_onboarding_form, NULL
  );
  PERFORM public.sync_saas_user_roles(v_user_id);

  UPDATE public.company_invites
  SET status = 'accepted', accepted_at = now(), accepted_by = v_user_id
  WHERE id = v_invite_id AND status = 'pending';

  RETURN jsonb_build_object(
    'ok', true,
    'org_id', v_org_id,
    'role', v_membership_role,
    'job_function', v_job_function
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.accept_company_invite_token(text) TO authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828300000_pos_registers_unique_per_brand.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- Register names are unique per organization + brand, not org-wide.
-- Opening Settings used to auto-insert "Main till", so creating "Main Till"
-- for another brand (or the same brand) hit idx_pos_registers_org_name.

DROP INDEX IF EXISTS public.idx_pos_registers_org_name;

-- COALESCE so two brandless tills cannot share a name (NULL ≠ NULL in unique indexes).
CREATE UNIQUE INDEX IF NOT EXISTS idx_pos_registers_org_brand_name
  ON public.pos_registers (
    org_id,
    COALESCE(company_id, '00000000-0000-0000-0000-000000000000'::uuid),
    lower(btrim(name))
  );

COMMENT ON INDEX public.idx_pos_registers_org_brand_name IS
  'One till name per org brand. Different brands may both use Main till.';

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828310000_pos_only_staff_scope.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- POS-only staff scope: not a second login. Same Auth + memberships.job_function = pos.
-- Cashiers cannot read back-office financial rows via RLS. Checkout clients stay readable.
-- Invite URL is /pos/invite/:token. Optional register_id is the till (not a store).

CREATE OR REPLACE FUNCTION public.is_pos_only_staff()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.memberships m
    JOIN public.organizations o ON o.id = m.org_id
    WHERE m.user_id = auth.uid()
      AND lower(trim(m.role)) = 'employee'
      AND public.normalize_job_function(m.job_function) = 'pos'
      AND o.owner_id IS DISTINCT FROM auth.uid()
  );
$$;

COMMENT ON FUNCTION public.is_pos_only_staff() IS
  'True when the signed-in user is an invited till cashier (employee + job_function pos), not the org owner.';

GRANT EXECUTE ON FUNCTION public.is_pos_only_staff() TO authenticated;

CREATE OR REPLACE FUNCTION public.can_read_org_financial_row(
  target_org_id uuid,
  row_user_id uuid DEFAULT NULL,
  row_created_by uuid DEFAULT NULL,
  row_created_by_id uuid DEFAULT NULL
)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.memberships m
    WHERE m.org_id = target_org_id
      AND m.user_id = auth.uid()
  )
  AND NOT public.is_pos_only_staff()
  AND (
    public.is_admin()
    OR public.is_company_manager_for_org(target_org_id)
    OR row_user_id = auth.uid()
    OR row_created_by = auth.uid()
    OR row_created_by_id = auth.uid()
  );
$$;

COMMENT ON FUNCTION public.can_read_org_financial_row(uuid, uuid, uuid, uuid) IS
  'Platform admin + company managers see all org rows; employees see only rows they own/created. POS-only staff never read invoice/quote/payslip financials.';

DO $$
BEGIN
  IF to_regclass('public.clients') IS NOT NULL THEN
    DROP POLICY IF EXISTS "pos staff select clients for checkout" ON public.clients;
    CREATE POLICY "pos staff select clients for checkout" ON public.clients
      FOR SELECT
      USING (
        public.is_pos_only_staff()
        AND EXISTS (
          SELECT 1 FROM public.memberships m
          WHERE m.org_id = clients.org_id AND m.user_id = auth.uid()
        )
      );
  END IF;
END $$;

ALTER TABLE public.company_invites
  ADD COLUMN IF NOT EXISTS register_id uuid;

COMMENT ON COLUMN public.company_invites.register_id IS
  'Optional pos_registers.id the cashier should use after accept. Not a store/location table.';

DO $$
BEGIN
  IF to_regclass('public.pos_registers') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM pg_constraint WHERE conname = 'company_invites_register_id_fkey'
     ) THEN
    ALTER TABLE public.company_invites
      ADD CONSTRAINT company_invites_register_id_fkey
      FOREIGN KEY (register_id) REFERENCES public.pos_registers(id) ON DELETE SET NULL;
  END IF;
EXCEPTION
  WHEN duplicate_object THEN NULL;
END $$;

CREATE OR REPLACE FUNCTION public.validate_company_invite_token(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.company_invites%ROWTYPE;
  v_org_name text;
BEGIN
  IF p_token IS NULL OR trim(p_token) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_token');
  END IF;

  SELECT * INTO v_row
  FROM public.company_invites
  WHERE token = trim(p_token)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_row.status <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', v_row.status);
  END IF;

  IF v_row.expires_at < now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'expired');
  END IF;

  SELECT o.name INTO v_org_name
  FROM public.organizations o
  WHERE o.id = v_row.org_id;

  RETURN jsonb_build_object(
    'ok', true,
    'invite_id', v_row.id,
    'email', v_row.email,
    'role', v_row.role,
    'job_function', public.normalize_job_function(coalesce(v_row.job_function, 'general')),
    'source', coalesce(v_row.source, 'company_admin'),
    'org_id', v_row.org_id,
    'company_name', coalesce(v_org_name, 'your company'),
    'expires_at', v_row.expires_at,
    'transfer_org_ownership', coalesce(v_row.transfer_org_ownership, false),
    'register_id', v_row.register_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.validate_company_invite_token(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validate_company_invite_token(text) TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.accept_company_invite_token(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_meta jsonb;
  v_invite_id uuid;
  v_org_id uuid;
  v_role text;
  v_membership_role text;
  v_job_function text;
  v_email text;
  v_onboarding_form text;
  v_register_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated');
  END IF;

  v_meta := public.validate_company_invite_token(p_token);
  IF (v_meta->>'ok')::boolean IS NOT TRUE THEN
    RETURN v_meta;
  END IF;

  v_invite_id := (v_meta->>'invite_id')::uuid;
  v_org_id := (v_meta->>'org_id')::uuid;
  v_role := lower(trim(v_meta->>'role'));
  v_job_function := public.normalize_job_function(
    COALESCE(v_meta->>'job_function', 'general')
  );
  IF lower(trim(coalesce(v_meta->>'source', ''))) = 'pos' THEN
    v_job_function := 'pos';
  END IF;
  BEGIN
    v_register_id := NULLIF(v_meta->>'register_id', '')::uuid;
  EXCEPTION
    WHEN others THEN
      v_register_id := NULL;
  END;

  SELECT lower(trim(email)) INTO v_email FROM auth.users WHERE id = v_user_id;
  IF v_email IS NULL OR v_email <> lower(trim(v_meta->>'email')) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'email_mismatch');
  END IF;

  v_membership_role := CASE
    WHEN v_role IN ('admin', 'owner', 'company_admin') THEN 'admin'
    WHEN v_role = 'manager' THEN 'manager'
    ELSE 'employee'
  END;

  IF v_job_function = 'pos' THEN
    v_membership_role := 'employee';
  END IF;

  v_onboarding_form := CASE
    WHEN v_membership_role IN ('admin', 'owner') THEN 'admin'
    ELSE 'member'
  END;

  IF EXISTS (
    SELECT 1 FROM public.memberships m
    WHERE m.org_id = v_org_id AND m.user_id = v_user_id
  ) THEN
    UPDATE public.memberships
    SET role = v_membership_role,
        job_function = v_job_function
    WHERE org_id = v_org_id AND user_id = v_user_id;
  ELSE
    INSERT INTO public.memberships (org_id, user_id, role, job_function)
    VALUES (v_org_id, v_user_id, v_membership_role, v_job_function);
  END IF;

  IF coalesce((v_meta->>'transfer_org_ownership')::boolean, false) THEN
    UPDATE public.organizations SET owner_id = v_user_id WHERE id = v_org_id;
    UPDATE public.memberships SET role = 'owner', job_function = 'general' WHERE org_id = v_org_id AND user_id = v_user_id;
    v_onboarding_form := 'admin';
    v_membership_role := 'owner';
    v_job_function := 'general';
  END IF;

  PERFORM public.upsert_user_company_role(
    v_user_id, v_org_id, public.normalize_company_role(v_membership_role), v_onboarding_form, NULL
  );
  PERFORM public.sync_saas_user_roles(v_user_id);

  IF v_job_function = 'pos' AND v_register_id IS NOT NULL AND to_regclass('public.pos_registers') IS NOT NULL THEN
    UPDATE public.pos_registers
    SET assigned_staff_id = v_user_id
    WHERE id = v_register_id
      AND org_id = v_org_id;
  END IF;

  UPDATE public.company_invites
  SET status = 'accepted', accepted_at = now(), accepted_by = v_user_id
  WHERE id = v_invite_id AND status = 'pending';

  RETURN jsonb_build_object(
    'ok', true,
    'org_id', v_org_id,
    'role', v_membership_role,
    'job_function', v_job_function,
    'scope', CASE WHEN v_job_function = 'pos' THEN 'pos' ELSE 'paidly' END
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.accept_company_invite_token(text) TO authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- supabase/migrations/20260828320000_pos_customers.sql
-- ═══════════════════════════════════════════════════════════════════════════

-- POS customers: same public.clients SoR, not a second CRM table.
-- POS-only staff may SELECT/INSERT only rows with pos_enabled = true.
-- Owners/admins keep full dashboard access via existing org member policies.
-- Till checkout must not enumerate the general Paidly client list.

ALTER TABLE public.clients
  ADD COLUMN IF NOT EXISTS pos_enabled boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN public.clients.pos_enabled IS
  'When true, this client is a POS customer (created on the till or explicitly enabled). POS-only staff may only see these rows.';

DO $$
BEGIN
  IF to_regclass('public.pos_sales_events') IS NOT NULL THEN
    UPDATE public.clients c
    SET pos_enabled = true
    WHERE c.pos_enabled IS NOT TRUE
      AND EXISTS (
        SELECT 1
        FROM public.pos_sales_events e
        WHERE e.client_id = c.id
          AND e.org_id = c.org_id
      );
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_clients_org_pos_enabled
  ON public.clients (org_id, name)
  WHERE pos_enabled = true;

CREATE OR REPLACE FUNCTION public.enforce_pos_customer_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF public.is_pos_only_staff() THEN
    NEW.pos_enabled := true;
    NEW.internal_notes := NULL;
    NEW.notes := NULL;
    NEW.tax_id := NULL;
    NEW.fax := NULL;
    NEW.alternate_email := NULL;
    NEW.website := NULL;
    NEW.address := NULL;
    NEW.industry := NULL;
    NEW.contact_person := NULL;
    IF TG_OP = 'INSERT' THEN
      NEW.created_by_id := COALESCE(NEW.created_by_id, auth.uid());
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_pos_customer_write() IS
  'POS-only cashiers can only write POS customer rows (name/phone/email). CRM fields stay empty.';

DROP TRIGGER IF EXISTS trg_enforce_pos_customer_write ON public.clients;
CREATE TRIGGER trg_enforce_pos_customer_write
  BEFORE INSERT OR UPDATE ON public.clients
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_pos_customer_write();

DROP POLICY IF EXISTS "pos staff select clients for checkout" ON public.clients;
DROP POLICY IF EXISTS "pos staff select pos customers" ON public.clients;
DROP POLICY IF EXISTS "pos staff insert pos customers" ON public.clients;
DROP POLICY IF EXISTS "pos staff update own pos customers" ON public.clients;

CREATE POLICY "pos staff select pos customers"
  ON public.clients
  FOR SELECT
  USING (
    public.is_pos_only_staff()
    AND clients.pos_enabled = true
    AND EXISTS (
      SELECT 1 FROM public.memberships m
      WHERE m.org_id = clients.org_id AND m.user_id = auth.uid()
    )
  );

CREATE POLICY "pos staff insert pos customers"
  ON public.clients
  FOR INSERT
  WITH CHECK (
    public.is_pos_only_staff()
    AND clients.pos_enabled = true
    AND COALESCE(clients.created_by_id, auth.uid()) = auth.uid()
    AND EXISTS (
      SELECT 1 FROM public.memberships m
      WHERE m.org_id = clients.org_id AND m.user_id = auth.uid()
    )
  );

CREATE POLICY "pos staff update own pos customers"
  ON public.clients
  FOR UPDATE
  USING (
    public.is_pos_only_staff()
    AND clients.pos_enabled = true
    AND clients.created_by_id = auth.uid()
    AND EXISTS (
      SELECT 1 FROM public.memberships m
      WHERE m.org_id = clients.org_id AND m.user_id = auth.uid()
    )
  )
  WITH CHECK (
    public.is_pos_only_staff()
    AND clients.pos_enabled = true
    AND clients.created_by_id = auth.uid()
    AND EXISTS (
      SELECT 1 FROM public.memberships m
      WHERE m.org_id = clients.org_id AND m.user_id = auth.uid()
    )
  );
